using System.Text.Json;
using WAID.Application.Services;
namespace WAID.Infrastructure.Persistence;
public sealed class SqliteRepairOrchestrationRepository(WaidDatabase database):IRepairOrchestrationRepository
{
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 public async Task SaveAsync(RepairOrchestrationRecord record,CancellationToken token){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="INSERT INTO repair_orchestrations(id,repair_id,created_utc,updated_utc,stage,simulation_version,simulation_fingerprint,simulated_utc,orchestration_json)VALUES($id,$repair,$created,$updated,$stage,$simulationVersion,$fingerprint,$simulated,$json) ON CONFLICT(id) DO UPDATE SET updated_utc=$updated,stage=$stage,simulation_version=$simulationVersion,simulation_fingerprint=$fingerprint,simulated_utc=$simulated,orchestration_json=$json";q.Parameters.AddWithValue("$id",record.Id.ToString());q.Parameters.AddWithValue("$repair",record.RepairId);q.Parameters.AddWithValue("$created",record.CreatedAtUtc.ToString("O"));q.Parameters.AddWithValue("$updated",record.UpdatedAtUtc.ToString("O"));q.Parameters.AddWithValue("$stage",(int)record.Stage);q.Parameters.AddWithValue("$simulationVersion",(object?)record.Simulation?.SimulationVersion??DBNull.Value);q.Parameters.AddWithValue("$fingerprint",(object?)record.Simulation?.Fingerprint??DBNull.Value);q.Parameters.AddWithValue("$simulated",(object?)record.Simulation?.SimulatedAtUtc.ToString("O")??DBNull.Value);q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(record,Json));await q.ExecuteNonQueryAsync(token).ConfigureAwait(false);}
 public async Task<RepairOrchestrationRecord?>GetAsync(Guid id,CancellationToken token){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT orchestration_json FROM repair_orchestrations WHERE id=$id";q.Parameters.AddWithValue("$id",id.ToString());var json=await q.ExecuteScalarAsync(token).ConfigureAwait(false)as string;return json is null?null:Decode(json);}
 public async Task<IReadOnlyList<RepairOrchestrationRecord>>GetRecentAsync(int count,CancellationToken token){if(count is<1 or>500)throw new ArgumentOutOfRangeException(nameof(count));await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT orchestration_json FROM repair_orchestrations ORDER BY updated_utc DESC,id DESC LIMIT $count";q.Parameters.AddWithValue("$count",count);return await Read(q,token);}
 public async Task<IReadOnlyList<RepairOrchestrationRecord>>GetNonTerminalAsync(CancellationToken token){await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT orchestration_json FROM repair_orchestrations WHERE stage NOT IN ($committed,$rolled,$failed,$cancelled,$recovery) ORDER BY updated_utc";q.Parameters.AddWithValue("$committed",(int)RepairOrchestrationStage.Committed);q.Parameters.AddWithValue("$rolled",(int)RepairOrchestrationStage.RolledBack);q.Parameters.AddWithValue("$failed",(int)RepairOrchestrationStage.Failed);q.Parameters.AddWithValue("$cancelled",(int)RepairOrchestrationStage.Cancelled);q.Parameters.AddWithValue("$recovery",(int)RepairOrchestrationStage.RecoveryRequired);return await Read(q,token);}
 private static async Task<IReadOnlyList<RepairOrchestrationRecord>>Read(Microsoft.Data.Sqlite.SqliteCommand q,CancellationToken token){var items=new List<RepairOrchestrationRecord>();await using var r=await q.ExecuteReaderAsync(token).ConfigureAwait(false);while(await r.ReadAsync(token).ConfigureAwait(false))items.Add(Decode(r.GetString(0)));return items;}
 private static RepairOrchestrationRecord Decode(string json)=>JsonSerializer.Deserialize<RepairOrchestrationRecord>(json,Json)??throw new InvalidDataException("Stored repair orchestration is invalid.");
}
